package e.e.a;
import java.io.*;import java.util.*;import android.content.*;import android.preference.PreferenceManager;
public final class PrivatePackTest {
 public static void main(String[] args)throws Exception{
  PreferenceManager.prefs=(SharedPreferences)CacheDefaultTest.preferences(SharedPreferences.class);File base=new File(args[0]);base.mkdirs();Context context=new Context(base,base);File root=new File(base,"old-native-cache");root.mkdirs();File archive=new File(root,"sm2.ncache");byte[] playlist="#EXTM3U\n#EXTINF:1\nsm2_asset_0.bin\n#EXT-X-ENDLIST\n".getBytes("UTF-8"),asset={1,2,3,4,5};List<CachePackIndex.Entry> index=new ArrayList<>();index.add(new CachePackIndex.Entry("sm2.m3u8",0,playlist.length,1));index.add(new CachePackIndex.Entry("sm2_asset_0.bin",playlist.length,asset.length,1));try(OutputStream out=new FileOutputStream(archive)){out.write(playlist);out.write(asset);CachePackIndex.finish(out,index);}new File(root,"sm2.mp4").createNewFile();CacheFile f=new CacheFile(root,"sm2.m3u8");if(!f.isFile()||f.length()!=playlist.length)throw new AssertionError("native packed playlist metadata");try(InputStream in=new CacheInputStream(f)){byte[] got=new byte[playlist.length];int n=in.read(got);if(n!=got.length||!Arrays.equals(got,playlist)||in.read()!=-1)throw new AssertionError("native packed playlist limits");}try(InputStream in=new CacheInputStream(new CacheFile(root,"sm2_asset_0.bin"))){if(in.read()!=1||in.skip(2)!=2||in.read()!=4||in.read()!=5||in.read()!=-1)throw new AssertionError("native packed range reads");}
  CacheFile missing=new CacheFile(root,"sm99.m3u8");if(missing.exists()||missing.isFile()||missing.length()!=0)throw new AssertionError("missing archive must not recurse or crash");for(File entry:new CacheFile(root.getPath()).listFiles())if(!(entry instanceof CacheFile))throw new AssertionError("native rows retain file abstraction");
  System.out.println("Copied native cache containers: metadata, playlist/asset reads, boundaries and missing-file handling passed");
 }
}
